function safeMovieText(s){return personLockText(String(s).replace(/多年后|重逢|错过|告别|离开|分开|旧恋人|来不及|遗憾/g,m=>({多年后:'今天',重逢:'碰面',错过:'绕路',告别:'散场',离开:'走开一会儿',分开:'各忙各的',旧恋人:'熟悉的人',来不及:'差一点',遗憾:'小插曲'}[m]||m)))}
