function play(){let files=[...($('#chat-file')?.files||[])],pasted=$('#chat-paste')?.value.trim();if(files.length&&!importedChatText&&!pasted){let hasImage=files.some(isImageFile);setImportFeedback(hasImage?'截图已上传，但还没有识别出聊天文字':'你们的聊天还没读取完成，请稍等一下再开始放映',hasImage?'当前没有拿到可用于生成的聊天文本。请粘贴截图里的文字，或在 Vercel 配置视觉 OCR 模型后重新上传截图。':'文件还在读取中，请稍等几秒。','warn');sfx('deny');return}story=lockStoryText(buildFilm());if(story.chatUsed)setImportFeedback(`已用于生成 · ${importedChatName||'你们的聊天'} · ${story.chatLineCount} 条`,`本次电影已使用你们整理后的聊天。\n剧情线索：${(story.chatHints||'').replace(/ \/ /g,'、')}`,'ok');posterCount=0;posterIndex=-1;posterHistory=[];$('.mini-poster').classList.remove('generated');$('.poster-image').removeAttribute('src');$('.poster-count').textContent='0 / 5';$('.poster-generate small').textContent='首次免费 · 还可生成 5 次';updatePosterLibrary();render();show('trailer');let lines=story.trailerLines||['银幕亮起以前','请记住那个被留下的物件','答案不会出现在第一场戏里'],topics=story.chatUsed?story.words:[...story.words,'天气','早餐','晚霞','电影','做梦','生日','旅行','照片','周末','想念','到家了吗','早点休息','下次一起'],line=$('.trailer-line'),wordbox=$('.wordstorm');wordbox.innerHTML='';clearTimeout(timer);let narrate=i=>{if(i>=lines.length){line.classList.remove('visible');timer=setTimeout(()=>flashWord(0),700);return}line.classList.remove('visible');timer=setTimeout(()=>{line.textContent=personLockText(lines[i]);line.classList.add('visible');timer=setTimeout(()=>narrate(i+1),1900+Math.min(lines[i].length*28,700))},420)},flashWord=i=>{if(i>=topics.length){timer=setTimeout(()=>startTicketMachine(),650);return}let w=document.createElement('i');w.textContent=personLockText(topics[i]);w.style.left=8+Math.random()*84+'%';w.style.top=8+Math.random()*84+'%';w.style.fontSize=14+Math.random()*24+'px';wordbox.append(w);timer=setTimeout(()=>flashWord(i+1),150)};narrate(0)}
