function makeTicketData(force=false){if(ticketData&&!force)return ticketData;let row=5+randNum(8),seat=10+randNum(12),date=`2026.08.${pad2(18+randNum(12))}`,time=pick(['18:30','19:20','19:30','20:00','20:20']),hall='Hall '+pad2(1+randNum(6)),order=String(Date.now()).slice(-6)+String(100000+randNum(900000)),eggs=['谢谢你来到这场故事里。','这一场电影，主演一直都是你。','请收好这张票，故事马上开场。','愿这张票，把今晚留得再久一点。','散场以后，也别忘记看看身边的人。','如果还想继续，请在片尾之后等TA。'];ticketData={date,time,hall,row,seat,order,egg:pick(eggs),thumb:paintPosterArt(story,hashText(story.title+'ticket'+ticketReroll),ticketReroll%8,ticketReroll%5)};ticketReroll++;return ticketData}
function makeBarcodeSvg(value){let seed=hashText(String(value)),x=4,rects=[];for(let i=0;i<42&&x<144;i++){let bw=1+((seed>>>(i%16))%4),gap=1+((seed>>((i+3)%16))%3);rects.push(`<rect x="${x}" y="3" width="${bw}" height="34"/>`);x+=bw+gap}return `<svg class="ticket-barcode-svg" viewBox="0 0 148 40" width="148" height="40" preserveAspectRatio="none" aria-label="barcode"><rect width="148" height="40" fill="#fff"/><g fill="#15110c">${rects.join('')}</g></svg>`}
